1	package columna
2	
3	import (
4		"encoding/json"
5		"math"
6		"strings"
7	)
8	
9	// Predicate operators accepted by POST /query.
10	const (
11		OpEq      = "="
12		OpLt      = "<"
13		OpGt      = ">"
14		OpLte     = "<="
15		OpGte     = ">="
16		OpBetween = "between"
17	)
18	
19	// Aggregation functions accepted by POST /query.
20	const (
21		AggCount = "count"
22		AggSum   = "sum"
23		AggMin   = "min"
24		AggMax   = "max"
25	)
26	
27	// Predicate is one pushed-down filter condition.
28	type Predicate struct {
29		Column string   `json:"column"`
30		Op     string   `json:"op"`
31		Value  *Value   `json:"-"`
32		Lo     *Value   `json:"-"`
33		Hi     *Value   `json:"-"`
34		Raw    []string `json:"-"`
35	}
36	
37	// Query is a projection / filter / aggregation request.
38	//
39	// Pages (the JSON field max_pages_per_group) bounds the scan: only the first
40	// Pages pages of each column in each row group are considered. Pages beyond the
41	// bound are ignored by pushdown and by a full scan alike, so both modes still
42	// return the same rows.
43	type Query struct {
44		Table      string      `json:"table"`
45		Projection []string    `json:"projection"`
46		Predicates []Predicate `json:"predicates"`
47		Aggregates []Aggregate `json:"aggregates"`
48		Limit      *int        `json:"limit"`
49		Pushdown   *bool       `json:"pushdown"`
50		Pages      *int        `json:"max_pages_per_group"`
51	}
52	
53	// Aggregate is one aggregation expression.
54	type Aggregate struct {
55		Func   string `json:"func"`
56		Column string `json:"column"`
57	}
58	
59	// QueryResult is the response body of POST /query.
60	type QueryResult struct {
61		Columns       []string         `json:"columns"`
62		Rows          []map[string]any `json:"rows"`
63		RowCount      int              `json:"row_count"`
64		ScannedRows   int              `json:"scanned_rows"`
65		ScannedGroups int              `json:"scanned_row_groups"`
66		ScannedPages  int              `json:"scanned_pages"`
67		SkippedPages  int              `json:"skipped_pages"`
68		Pushdown      bool             `json:"pushdown"`
69		MatchedRows   int              `json:"matched_rows"`
70	}
71	
72	var validOps = map[string]bool{OpEq: true, OpLt: true, OpGt: true, OpLte: true, OpGte: true, OpBetween: true}
73	var validAggs = map[string]bool{AggCount: true, AggSum: true, AggMin: true, AggMax: true}
74	
75	func decodePredicate(raw map[string]json.RawMessage) (Predicate, error) {
76		allowed := map[string]bool{"column": true, "op": true, "value": true, "lo": true, "hi": true}
77		for key := range raw {
78			if !allowed[key] {
79				return Predicate{}, Validationf("unknown predicate field %q", key)
80			}
81		}
82		predicate := Predicate{}
83		columnRaw, ok := raw["column"]
84		if !ok {
85			return Predicate{}, Validationf("predicate is missing column")
86		}
87		if err := json.Unmarshal(columnRaw, &predicate.Column); err != nil {
88			return Predicate{}, Validationf("predicate column must be a string")
89		}
90		opRaw, ok := raw["op"]
91		if !ok {
92			return Predicate{}, Validationf("predicate is missing op")
93		}
94		if err := json.Unmarshal(opRaw, &predicate.Op); err != nil {
95			return Predicate{}, Validationf("predicate op must be a string")
96		}
97		if !validOps[predicate.Op] {
98			return Predicate{}, Validationf("unsupported predicate op %q", predicate.Op)
99		}
100		switch predicate.Op {
101		case OpBetween:
102			if _, ok := raw["value"]; ok {
103				return Predicate{}, Validationf("between takes lo and hi, not value")
104			}
105			lo, err := decodePredicateValue(raw["lo"], "lo", predicate.Op)
106			if err != nil {
107				return Predicate{}, err
108			}
109			hi, err := decodePredicateValue(raw["hi"], "hi", predicate.Op)
110			if err != nil {
111				return Predicate{}, err
112			}
113			predicate.Lo, predicate.Hi = lo, hi
114		default:
115			if _, ok := raw["lo"]; ok {
116				return Predicate{}, Validationf("op %q takes value, not lo", predicate.Op)
117			}
118			if _, ok := raw["hi"]; ok {
119				return Predicate{}, Validationf("op %q takes value, not hi", predicate.Op)
120			}
121			value, err := decodePredicateValue(raw["value"], "value", predicate.Op)
122			if err != nil {
123				return Predicate{}, err
124			}
125			predicate.Value = value
126		}
127		return predicate, nil
128	}
129	
130	func decodePredicateValue(raw json.RawMessage, field, op string) (*Value, error) {
131		if len(raw) == 0 {
132			return nil, Validationf("predicate op %q requires %s", op, field)
133		}
134		if string(raw) == "null" {
135			return nil, Validationf("predicate %s must not be null", field)
136		}
137		value := Value{}
138		if err := json.Unmarshal(raw, &value); err != nil {
139			return nil, Validationf("predicate %s must be a number, bool or string", field)
140		}
141		return &value, nil
142	}
143	
144	func (p Predicate) bind(schema Schema) (Predicate, error) {
145		if !validOps[p.Op] {
146			return Predicate{}, Validationf("unsupported predicate op %q", p.Op)
147		}
148		column, ok := schema.Column(p.Column)
149		if !ok {
150			return Predicate{}, Validationf("unknown column %q", p.Column)
151		}
152		bind := func(v *Value, field string) error {
153			if v == nil {
154				return Validationf("predicate on %q requires %s", p.Column, field)
155			}
156			coerceNumber(v, column.Type)
157			if v.Kind != column.Type {
158				return Validationf("predicate %s %s expects a %s value, got %s", p.Column, field, column.Type, v.Kind)
159			}
160			if column.Type == TypeString && p.Op != OpEq && p.Op != OpBetween {
161				return Validationf("string columns support only \"=\" and \"between\"")
162			}
163			return nil
164		}
165		if p.Op == OpBetween {
166			if err := bind(p.Lo, "lo"); err != nil {
167				return Predicate{}, err
168			}
169			if err := bind(p.Hi, "hi"); err != nil {
170				return Predicate{}, err
171			}
172			if compareValues(*p.Lo, *p.Hi) > 0 {
173				return Predicate{}, Validationf("between lo must not exceed hi")
174			}
175			return p, nil
176		}
177		if err := bind(p.Value, "value"); err != nil {
178			return Predicate{}, err
179		}
180		return p, nil
181	}
182	
183	// coerceNumber lets one JSON number form serve both numeric column types: an
184	// int64 predicate value becomes a float64 for a float64 column, and an integral
185	// float64 value becomes an int64 for an int64 column. Anything else keeps its
186	// kind and is rejected by the caller.
187	func coerceNumber(v *Value, typ string) {
188		const (
189			minInt64AsFloat = -9223372036854775808.0
190			maxInt64AsFloat = 9223372036854775808.0
191		)
192		switch {
193		case typ == TypeFloat64 && v.Kind == TypeInt64:
194			*v = FloatValue(float64(v.Int))
195		case typ == TypeInt64 && v.Kind == TypeFloat64 &&
196			v.Float == math.Trunc(v.Float) && v.Float >= minInt64AsFloat && v.Float < maxInt64AsFloat:
197			*v = IntValue(int64(v.Float))
198		}
199	}
200	
201	// matches evaluates the predicate against one non-null value.
202	func (p Predicate) matches(v Value, typ string) bool {
203		if v.Null {
204			return false
205		}
206		switch p.Op {
207		case OpEq:
208			switch typ {
209			case TypeString:
210				return v.Str == p.Value.Str
211			case TypeBool:
212				return v.Bool == p.Value.Bool
213			default:
214				return compareValues(v, *p.Value) == 0
215			}
216		case OpBetween:
217			if typ == TypeString {
218				return v.Str >= p.Lo.Str && v.Str <= p.Hi.Str
219			}
220			return compareValues(v, *p.Lo) >= 0 && compareValues(v, *p.Hi) <= 0
221		case OpLt, OpLte, OpGt, OpGte:
222			if typ == TypeString {
223				return false // ordering operators are rejected for string columns
224			}
225			cmp := compareValues(v, *p.Value)
226			switch p.Op {
227			case OpLt:
228				return cmp < 0
229			case OpLte:
230				return cmp <= 0
231			case OpGt:
232				return cmp > 0
233			case OpGte:
234				return cmp >= 0
235			}
236		}
237		return false
238	}
239	
240	// compareValues orders two non-null values of the same logical type. int64 and
241	// float64 comparisons stay inside their own domain, so integers beyond 2^53
242	// keep full precision, and bools order false < true.
243	func compareValues(a, b Value) int {
244		switch {
245		case a.Kind == TypeInt64 && b.Kind == TypeInt64:
246			switch {
247			case a.Int < b.Int:
248				return -1
249			case a.Int > b.Int:
250				return 1
251			default:
252				return 0
253			}
254		case a.Kind == TypeBool && b.Kind == TypeBool:
255			switch {
256			case a.Bool == b.Bool:
257				return 0
258			case !a.Bool:
259				return -1
260			default:
261				return 1
262			}
263		case a.Kind == TypeString && b.Kind == TypeString:
264			switch {
265			case a.Str < b.Str:
266				return -1
267			case a.Str > b.Str:
268				return 1
269			default:
270				return 0
271			}
272		default:
273			x, _ := a.Number()
274			y, _ := b.Number()
275			switch {
276			case x < y:
277				return -1
278			case x > y:
279				return 1
280			default:
281				return 0
282			}
283		}
284	}
285	
286	// pageMatches uses page statistics to decide whether a page can hold a
287	// matching row. It may only return false when no row in the page can match.
288	func (p Predicate) pageMatches(stats PageStats, rows int64) bool {
289		if rows == 0 {
290			return false
291		}
292		if stats.Nulls == rows {
293			return false // every value is NULL, and NULL never matches
294		}
295		if !stats.Set {
296			return true
297		}
298		// The statistics hold the min and max of the non-null values, so an
299		// operator can only match if its value range overlaps [min, max].
300		switch p.Op {
301		case OpBetween:
302			return compareValues(stats.Max, *p.Lo) >= 0 && compareValues(stats.Min, *p.Hi) <= 0
303		case OpEq:
304			return compareValues(stats.Min, *p.Value) <= 0 && compareValues(stats.Max, *p.Value) >= 0
305		case OpLt:
306			return compareValues(stats.Min, *p.Value) < 0
307		case OpLte:
308			return compareValues(stats.Min, *p.Value) <= 0
309		case OpGt:
310			return compareValues(stats.Max, *p.Value) > 0
311		case OpGte:
312			return compareValues(stats.Max, *p.Value) >= 0
313		}
314		return true
315	}
316	
317	func (q Query) bind(table *Table) (Query, error) {
318		if q.Table == "" {
319			return q, Validationf("table is required")
320		}
321		if q.Table != table.Name {
322			return q, Validationf("query targets table %q but table %q was loaded", q.Table, table.Name)
323		}
324		bound := q
325		if len(bound.Projection) == 0 && len(bound.Aggregates) == 0 {
326			for _, c := range table.Schema.Columns {
327				bound.Projection = append(bound.Projection, c.Name)
328			}
329		}
330		if len(bound.Aggregates) > 0 && len(q.Projection) > 0 {
331			return bound, Validationf("projection and aggregates are mutually exclusive")
332		}
333		for _, name := range bound.Projection {
334			if _, ok := table.Schema.Column(name); !ok {
335				return bound, Validationf("unknown column %q in projection", name)
336			}
337		}
338		for i := range bound.Predicates {
339			bound.Predicates[i].Column = strings.TrimSpace(bound.Predicates[i].Column)
340			predicate, err := bound.Predicates[i].bind(table.Schema)
341			if err != nil {
342				return bound, err
343			}
344			bound.Predicates[i] = predicate
345		}
346		for i, aggregate := range bound.Aggregates {
347			if !validAggs[aggregate.Func] {
348				return bound, Validationf("unsupported aggregate %q", aggregate.Func)
349			}
350			if aggregate.Func == AggCount && aggregate.Column == "" {
351				continue
352			}
353			column, ok := table.Schema.Column(aggregate.Column)
354			if !ok {
355				return bound, Validationf("unknown column %q in aggregate %d", aggregate.Column, i)
356			}
357			if aggregate.Func == AggSum && column.Type != TypeInt64 && column.Type != TypeFloat64 {
358				return bound, Validationf("sum requires an int64 or float64 column, got %s", column.Type)
359			}
360		}
361		if bound.Limit != nil && *bound.Limit < 0 {
362			return bound, Validationf("limit must not be negative")
363		}
364		if bound.Pages != nil && *bound.Pages < 0 {
365			return bound, Validationf("max_pages_per_group must not be negative")
366		}
367		return bound, nil
368	}
