1	package columna
2	
3	import (
4		"bytes"
5		"math"
6		"math/bits"
7	)
8	
9	// Page encodings supported inside a data page.
10	const (
11		EncodingPlain      = "plain"
12		EncodingDictionary = "dictionary"
13		EncodingRLE        = "rle"
14	)
15	
16	// PagePayload holds the encoded payload of one column page plus the
17	// encoding-specific header fields.
18	type PagePayload struct {
19		Encoding  string
20		DictSize  uint32
21		RunCount  uint32
22		IndexBits uint8
23		Payload   []byte
24	}
25	
26	// ---- primitive codecs -------------------------------------------------------
27	
28	func appendVarint(dst []byte, v uint64) []byte {
29		for v >= 0x80 {
30			dst = append(dst, byte(v)|0x80)
31			v >>= 7
32		}
33		return append(dst, byte(v))
34	}
35	
36	func readVarint(src []byte, off int) (uint64, int, error) {
37		var value uint64
38		var shift uint
39		for {
40			if off >= len(src) {
41				return 0, 0, Formatf("truncated varint")
42			}
43			b := src[off]
44			off++
45			if shift > 63 {
46				return 0, 0, Formatf("varint overflows 64 bits")
47			}
48			value |= uint64(b&0x7f) << shift
49			if b < 0x80 {
50				return value, off, nil
51			}
52			shift += 7
53		}
54	}
55	
56	// packBits writes values LSB-first: the first value occupies the low bits of
57	// byte 0, the next value continues in the following bits. Every value occupies
58	// exactly width bits, and the final partial byte is zero padded.
59	func packBits(values []uint64, width int) []byte {
60		if width == 0 {
61			return nil
62		}
63		out := make([]byte, (len(values)*width+7)/8)
64		bit := 0
65		for _, v := range values {
66			for i := 0; i < width; i++ {
67				if v>>uint(i)&1 == 1 {
68					out[bit/8] |= 1 << uint(bit%8)
69				}
70				bit++
71			}
72		}
73		return out
74	}
75	
76	func unpackBits(src []byte, width, count int) ([]uint64, error) {
77		if width == 0 {
78			return make([]uint64, count), nil
79		}
80		if len(src)*8 < count*width {
81			return nil, Formatf("bit-packed payload is truncated")
82		}
83		out := make([]uint64, count)
84		bit := 0
85		for i := 0; i < count; i++ {
86			var v uint64
87			for b := 0; b < width; b++ {
88				if src[bit/8]>>uint(bit%8)&1 == 1 {
89					v |= 1 << uint(b)
90				}
91				bit++
92			}
93			out[i] = v
94		}
95		return out, nil
96	}
97	
98	// PackNulls encodes the null map as 1 bit per value, LSB-first, where a set bit
99	// means NULL.
100	func PackNulls(values []Value) []byte {
101		out := make([]byte, (len(values)+7)/8)
102		for i, v := range values {
103			if v.Null {
104				out[i/8] |= 1 << uint(i%8)
105			}
106		}
107		return out
108	}
109	
110	func readNulls(src []byte, count int) ([]bool, error) {
111		if len(src) < (count+7)/8 {
112			return nil, Formatf("null bitmap is truncated")
113		}
114		nulls := make([]bool, count)
115		for i := 0; i < count; i++ {
116			nulls[i] = src[i/8]>>uint(i%8)&1 == 1
117		}
118		return nulls, nil
119	}
120	
121	// encodePlainValues returns the concatenation of the plain payloads of the
122	// non-null values in order (used for the value body and for dictionaries).
123	func encodePlainValues(values []Value, indices []int) []byte {
124		var out []byte
125		for _, i := range indices {
126			v := values[i]
127			switch v.Kind {
128			case TypeInt64:
129				out = appendLE64(out, uint64(v.Int))
130			case TypeFloat64:
131				out = appendLE64(out, math.Float64bits(v.Float))
132			case TypeBool:
133				if v.Bool {
134					out = append(out, 1)
135				} else {
136					out = append(out, 0)
137				}
138			default:
139				out = append(out, v.Str...)
140				out = append(out, 0)
141			}
142		}
143		return out
144	}
145	
146	func appendLE64(dst []byte, v uint64) []byte {
147		return append(dst,
148			byte(v), byte(v>>8), byte(v>>16), byte(v>>24),
149			byte(v>>32), byte(v>>40), byte(v>>48), byte(v>>56))
150	}
151	
152	func readLE64(src []byte, off int) (uint64, int, error) {
153		if off+8 > len(src) {
154			return 0, 0, Formatf("plain payload is truncated")
155		}
156		var v uint64
157		for i := 7; i >= 0; i-- {
158			v = v<<8 | uint64(src[off+i])
159		}
160		return v, off + 8, nil
161	}
162	
163	// decodePlainValues reads count values of the given type from a plain payload.
164	func decodePlainValues(src []byte, typ string, count int) ([]Value, error) {
165		out := make([]Value, count)
166		off := 0
167		for i := 0; i < count; i++ {
168			switch typ {
169			case TypeInt64:
170				raw, next, err := readLE64(src, off)
171				if err != nil {
172					return nil, err
173				}
174				off = next
175				out[i] = IntValue(int64(raw))
176			case TypeFloat64:
177				raw, next, err := readLE64(src, off)
178				if err != nil {
179					return nil, err
180				}
181				off = next
182				out[i] = FloatValue(math.Float64frombits(raw))
183			case TypeBool:
184				if off >= len(src) {
185					return nil, Formatf("plain payload is truncated")
186				}
187				out[i] = BoolValue(src[off] != 0)
188				off++
189			default:
190				end := off
191				for end < len(src) && src[end] != 0 {
192					end++
193				}
194				if end >= len(src) {
195					return nil, Formatf("string payload is missing its NUL terminator")
196				}
197				out[i] = StringValue(string(src[off:end]))
198				off = end + 1
199			}
200		}
201		return out, nil
202	}
203	
204	func plainEncodedSize(values []Value, indices []int) int {
205		size := 0
206		for _, i := range indices {
207			switch values[i].Kind {
208			case TypeInt64, TypeFloat64:
209				size += 8
210			case TypeBool:
211				size++
212			default:
213				size += len(values[i].Str) + 1
214			}
215		}
216		return size
217	}
218	
219	// ---- page encoders ----------------------------------------------------------
220	
221	// PageStats describes one column page or one row group.
222	type PageStats struct {
223		Nulls int64
224		Set   bool
225		Min   Value
226		Max   Value
227	}
228	
229	func (s PageStats) JSON() map[string]any {
230		out := map[string]any{"null_count": s.Nulls}
231		if s.Set {
232			out["min"] = s.Min.JSON()
233			out["max"] = s.Max.JSON()
234		} else {
235			out["min"] = nil
236			out["max"] = nil
237		}
238		return out
239	}
240	
241	func valuesStats(values []Value, indices []int) PageStats {
242		// An all-NULL page has no boundary values; leaving Min and Max as NULL is
243		// what makes the footer record them as absent instead of as an untyped
244		// value that no reader could decode.
245		stats := PageStats{Nulls: int64(len(values) - len(indices)), Min: NullValue(), Max: NullValue()}
246		for _, i := range indices {
247			v := values[i]
248			if !stats.Set {
249				stats.Set, stats.Min, stats.Max = true, v, v
250				continue
251			}
252			if less(v, stats.Min) {
253				stats.Min = v
254			}
255			if less(stats.Max, v) {
256				stats.Max = v
257			}
258		}
259		return stats
260	}
261	
262	// less orders two non-null values of the same logical type.
263	func less(a, b Value) bool {
264		switch a.Kind {
265		case TypeInt64:
266			return a.Int < b.Int
267		case TypeFloat64:
268			return a.Float < b.Float
269		case TypeBool:
270			return !a.Bool && b.Bool
271		default:
272			return a.Str < b.Str
273		}
274	}
275	
276	// encodePage builds the full page payload: the null bitmap followed by the
277	// encoding specific body. The layout is documented in README.md.
278	func encodePage(values []Value, typ string, requested string) (PagePayload, PageStats, error) {
279		nonNull := make([]int, 0, len(values))
280		for i := range values {
281			if !values[i].Null {
282				nonNull = append(nonNull, i)
283			}
284		}
285		for _, i := range nonNull {
286			if values[i].Kind != typ {
287				return PagePayload{}, PageStats{}, Validationf("value kind %q does not match column type %q", values[i].Kind, typ)
288			}
289		}
290		stats := valuesStats(values, nonNull)
291		bitmap := PackNulls(values)
292		var payload PagePayload
293		switch requested {
294		case EncodingPlain:
295			payload = PagePayload{Encoding: EncodingPlain, Payload: encodePlainValues(values, nonNull)}
296		case EncodingDictionary:
297			encoded, err := dictionaryBody(values, nonNull)
298			if err != nil {
299				return PagePayload{}, PageStats{}, err
300			}
301			payload = encoded
302		case EncodingRLE:
303			encoded, err := rleBody(values, nonNull)
304			if err != nil {
305				return PagePayload{}, PageStats{}, err
306			}
307			payload = encoded
308		default:
309			return PagePayload{}, PageStats{}, Validationf("unsupported encoding %q", requested)
310		}
311		full := make([]byte, 0, len(bitmap)+len(payload.Payload))
312		full = append(full, bitmap...)
313		full = append(full, payload.Payload...)
314		payload.Payload = full
315		return payload, stats, nil
316	}
317	
318	func dictionaryBody(values []Value, nonNull []int) (PagePayload, error) {
319		if len(nonNull) == 0 {
320			return PagePayload{Encoding: EncodingDictionary, IndexBits: 0}, nil
321		}
322		seen := map[string]int{}
323		var dict []int
324		var idxValues []uint64
325		for _, i := range nonNull {
326			key := valueKey(values[i])
327			pos, ok := seen[key]
328			if !ok {
329				pos = len(dict)
330				seen[key] = pos
331				dict = append(dict, i)
332			}
333			idxValues = append(idxValues, uint64(pos))
334		}
335		width := 0
336		if len(dict) > 1 {
337			width = bits.Len(uint(len(dict) - 1))
338		}
339		return PagePayload{
340			Encoding:  EncodingDictionary,
341			DictSize:  uint32(len(dict)),
342			IndexBits: uint8(width),
343			Payload:   append(encodePlainValues(values, dict), packBits(idxValues, width)...),
344		}, nil
345	}
346	
347	func valueKey(v Value) string {
348		switch v.Kind {
349		case TypeInt64:
350			return "i" + string(appendLE64(nil, uint64(v.Int)))
351		case TypeFloat64:
352			return "f" + string(appendLE64(nil, math.Float64bits(v.Float)))
353		case TypeBool:
354			if v.Bool {
355				return "b1"
356			}
357			return "b0"
358		default:
359			return "s" + v.Str
360		}
361	}
362	
363	func rleBody(values []Value, nonNull []int) (PagePayload, error) {
364		if len(nonNull) == 0 {
365			return PagePayload{Encoding: EncodingRLE, RunCount: 0}, nil
366		}
367		for i := 1; i < len(nonNull); i++ {
368			if nonNull[i] != nonNull[i-1]+1 {
369				return PagePayload{}, Validationf("rle encoding requires physically contiguous non-null values")
370			}
371		}
372		type run struct {
373			length int
374			sample int
375		}
376		var runs []run
377		for _, i := range nonNull {
378			if len(runs) > 0 && valueKey(values[runs[len(runs)-1].sample]) == valueKey(values[i]) {
379				runs[len(runs)-1].length++
380				continue
381			}
382			runs = append(runs, run{length: 1, sample: i})
383		}
384		body := bytes.Buffer{}
385		for _, r := range runs {
386			body.Write(appendVarint(nil, uint64(r.length)))
387		}
388		for _, r := range runs {
389			body.Write(encodePlainValues(values, []int{r.sample}))
390		}
391		return PagePayload{Encoding: EncodingRLE, RunCount: uint32(len(runs)), Payload: body.Bytes()}, nil
392	}
393	
394	// ---- page decoders ----------------------------------------------------------
395	
396	func decodePage(header PageHeader, payload []byte, valueCount int, typ string) ([]Value, error) {
397		nullBytes := (valueCount + 7) / 8
398		if len(payload) < nullBytes {
399			return nil, Formatf("page %d payload is truncated", header.PageIndex)
400		}
401		nulls, err := readNulls(payload[:nullBytes], valueCount)
402		if err != nil {
403			return nil, err
404		}
405		body := payload[nullBytes:]
406		nonNull := 0
407		for _, isNull := range nulls {
408			if !isNull {
409				nonNull++
410			}
411		}
412		var values []Value
413		switch header.Encoding {
414		case EncodingPlain:
415			values, err = decodePlainValues(body, typ, nonNull)
416		case EncodingDictionary:
417			values, err = decodeDictionary(header, body, nonNull, typ)
418		case EncodingRLE:
419			values, err = decodeRLE(header, body, nonNull)
420		default:
421			return nil, Formatf("unsupported encoding %q in page %d", header.Encoding, header.PageIndex)
422		}
423		if err != nil {
424			return nil, err
425		}
426		out := make([]Value, valueCount)
427		next := 0
428		for i := 0; i < valueCount; i++ {
429			if nulls[i] {
430				out[i] = NullValue()
431				continue
432			}
433			out[i] = values[next]
434			next++
435		}
436		return out, nil
437	}
438	
439	func decodeDictionary(header PageHeader, body []byte, nonNull int, typ string) ([]Value, error) {
440		if header.DictSize == 0 {
441			if nonNull != 0 {
442				return nil, Formatf("page %d has dictionary size 0 but %d non-null values", header.PageIndex, nonNull)
443			}
444			return nil, nil
445		}
446		dict, err := decodePlainValues(body, typ, int(header.DictSize))
447		if err != nil {
448			return nil, err
449		}
450		consumed := plainEncodedSize(dict, indexRange(len(dict)))
451		indices, err := unpackBits(body[consumed:], int(header.IndexBits), nonNull)
452		if err != nil {
453			return nil, err
454		}
455		out := make([]Value, nonNull)
456		for i, idx := range indices {
457			if idx >= uint64(len(dict)) {
458				return nil, Formatf("page %d dictionary index %d is out of range", header.PageIndex, idx)
459			}
460			out[i] = dict[idx]
461		}
462		return out, nil
463	}
464	
465	func indexRange(n int) []int {
466		out := make([]int, n)
467		for i := range out {
468			out[i] = i
469		}
470		return out
471	}
472	
473	func decodeRLE(header PageHeader, body []byte, nonNull int) ([]Value, error) {
474		runs := int(header.RunCount)
475		lengths := make([]int, runs)
476		off := 0
477		total := 0
478		for i := 0; i < runs; i++ {
479			value, next, err := readVarint(body, off)
480			if err != nil {
481				return nil, err
482			}
483			off = next
484			if value == 0 {
485				return nil, Formatf("page %d contains a zero-length run", header.PageIndex)
486			}
487			lengths[i] = int(value)
488			total += int(value)
489		}
490		if total != nonNull {
491			return nil, Formatf("page %d run lengths sum to %d but the page holds %d non-null values", header.PageIndex, total, nonNull)
492		}
493		// Run values follow the run-length block; the column type comes from the
494		// page header so every run value uses the same plain layout.
495		return decodeRunValues(body[off:], header, lengths)
496	}
497	
498	func decodeRunValues(body []byte, header PageHeader, lengths []int) ([]Value, error) {
499		typ := header.ColumnType
500		out := make([]Value, 0, len(lengths))
501		off := 0
502		for _, length := range lengths {
503			single, err := decodePlainValues(body[off:], typ, 1)
504			if err != nil {
505				return nil, err
506			}
507			size := plainEncodedSize(single, []int{0})
508			off += size
509			for i := 0; i < length; i++ {
510				out = append(out, single[0])
511			}
512		}
513		return out, nil
514	}
515	
516	// SortedForRLE reports whether the non-null prefix of values is strictly
517	// ascending, which is the precondition for run-length encoding to be lossless
518	// and useful.
519	func SortedForRLE(values []Value) bool {
520		previous := Value{}
521		seen := false
522		for _, v := range values {
523			if v.Null {
524				continue
525			}
526			if seen && less(v, previous) {
527				return false
528			}
529			previous, seen = v, true
530		}
531		return true
532	}
533	
534	func DistinctCount(values []Value) int {
535		seen := map[string]bool{}
536		for _, v := range values {
537			if v.Null {
538				continue
539			}
540			seen[valueKey(v)] = true
541		}
542		return len(seen)
543	}
