203	// idempotent runs operation once per key. Replaying a key returns the recorded
204	// status and response body; reusing it for a different operation is a
205	// conflict. Because a read-modify-write POST has exactly one request shape for
206	// a given operation, the body itself is not part of the key.
207	func (s *Service) idempotent(operation, key string, request any, run func() (int, any, error)) (int, json.RawMessage, error) {
208		if key == "" {
209			status, response, err := run()
210			if err != nil {
211				return 0, nil, err
212			}
213			raw, _ := json.Marshal(response)
214			return status, raw, nil
215		}
216		record := canonical(operation, request)
217		if existing, ok := s.completed[key]; ok {
218			var stored struct {
219				Request  string          `json:"request"`
220				Status   int             `json:"status"`
221				Response json.RawMessage `json:"response"`
222			}
223			if err := json.Unmarshal([]byte(existing), &stored); err == nil && stored.Request != "" {
224				if stored.Request != record {
225					return 0, nil, errorf(CodeIdempotency, "idempotency key %q was already used for another operation", key)
226				}
227				return stored.Status, stored.Response, nil
228			}
229		}
230		status, response, err := run()
231		if err != nil {
232			return 0, nil, err
233		}
234		body, err := json.Marshal(response)
235		if err != nil {
236			return 0, nil, err
237		}
238		entry, err := json.Marshal(map[string]any{
239			"request":  record,
240			"status":   status,
241			"response": json.RawMessage(body),
242		})
243		if err != nil {
244			return 0, nil, err
245		}
246		s.completed[key] = string(entry)
247		if err := s.persistIdempotency(); err != nil {
248			return 0, nil, err
249		}
250		return status, body, nil
251	}
252	
253	func (s *Service) persistIdempotency() error {
254		raw, err := json.Marshal(s.completed)
255		if err != nil {
256			return errorf(CodeInternal, "cannot encode the idempotency store: %v", err)
257		}
258		temp := s.sidecar + ".tmp"
259		if err := os.WriteFile(temp, raw, 0o644); err != nil {
260			return errorf(CodeInternal, "cannot write %s: %v", temp, err)
261		}
262		if err := os.Rename(temp, s.sidecar); err != nil {
263			return errorf(CodeInternal, "cannot replace %s: %v", s.sidecar, err)
264		}
265		return nil
266	}
267	
268	func canonical(operation string, request any) string {
269		raw, err := json.Marshal(map[string]any{"operation": operation, "request": request})
270		if err != nil {
271			return operation
272		}
273		return string(raw)
274	}
