276	// TableResult is the body of POST /tables.
277	type TableResult struct {
278		Name      string `json:"name"`
279		Schema    Schema `json:"schema"`
280		RowCount  int64  `json:"row_count"`
281		RowGroups int    `json:"row_groups"`
282	}
283	
284	func tableResult(table *Table) TableResult {
285		stats := table.Stats()
286		return TableResult{
287			Name:      table.Name,
288			Schema:    table.Schema,
289			RowCount:  stats.RowCount,
290			RowGroups: stats.RowGroupCount,
291		}
292	}
293	
294	// AppendResult is the body of POST /tables/{name}/rows.
295	type AppendResult struct {
296		Table         string        `json:"table"`
297		AppendedRows  int           `json:"appended_rows"`
298		RowCount      int64         `json:"row_count"`
299		RowGroupCount int           `json:"row_group_count"`
300		RowGroupIndex int           `json:"row_group_index"`
301		Encodings     []EncodingUse `json:"encodings"`
302		FileSize      int64         `json:"file_size"`
303	}
304	
305	// EncodingUse reports how many pages of one column used each encoding.
306	type EncodingUse struct {
307		Column string         `json:"column"`
308		Pages  map[string]int `json:"pages"`
309	}
310	
311	func appendResult(table *Table, appended int) AppendResult {
312		stats := table.Stats()
313		return AppendResult{
314			Table:         table.Name,
315			AppendedRows:  appended,
316			RowCount:      stats.RowCount,
317			RowGroupCount: stats.RowGroupCount,
318			RowGroupIndex: stats.RowGroupCount - 1,
319			Encodings:     encodingUse(table),
320			FileSize:      stats.FileSize,
321		}
322	}
323	
324	func encodingUse(table *Table) []EncodingUse {
325		groups := table.parsed.rowGroups
326		if len(groups) == 0 {
327			return []EncodingUse{}
328		}
329		group := groups[len(groups)-1]
330		out := make([]EncodingUse, 0, len(table.Schema.Columns))
331		for _, column := range table.Schema.Columns {
332			pages := map[string]int{
333				EncodingPlain:      0,
334				EncodingDictionary: 0,
335				EncodingRLE:        0,
336			}
337			for _, header := range group.Pages[column.Name] {
338				pages[header.Encoding]++
339			}
340			out = append(out, EncodingUse{Column: column.Name, Pages: pages})
341		}
342		return out
343	}
344	
345	// StatsResult is the body of GET /tables/{name}/stats.
346	type StatsResult struct {
347		Table    string    `json:"table"`
348		Schema   Schema    `json:"schema"`
349		Stats    FileStats `json:"stats"`
350		Checksum string    `json:"checksum"`
351	}
352	
353	// AppendRequest is the body of POST /tables/{name}/rows.
354	type AppendRequest struct {
355		Rows          json.RawMessage   `json:"rows"`
356		MaxPageValues *int              `json:"max_page_values"`
357		Encoding      map[string]string `json:"encoding"`
358	}
