96	func parseSchema(spec string) (columna.Schema, error) {
97		schema := columna.Schema{}
98		for _, field := range strings.Split(spec, ",") {
99			field = strings.TrimSpace(field)
100			if field == "" {
101				continue
102			}
103			parts := strings.SplitN(field, ":", 2)
104			if len(parts) != 2 {
105				return schema, fmt.Errorf("schema field %q must look like name:type", field)
106			}
107			column := columna.Column{Name: strings.TrimSpace(parts[0]), Type: strings.TrimSpace(parts[1])}
108			if strings.HasSuffix(column.Type, "?") {
109				column.Nullable = true
110				column.Type = strings.TrimSuffix(column.Type, "?")
111			}
112			schema.Columns = append(schema.Columns, column)
113		}
114		if err := schema.Validate(); err != nil {
115			return schema, err
116		}
117		return schema, nil
118	}
