120	func runCreate(args []string) error {
121		set := flag.NewFlagSet("create", flag.ContinueOnError)
122		file := set.String("file", "", "table file path")
123		spec := set.String("schema", "", "schema, e.g. 'id:int64,name:string?'")
124		if err := set.Parse(args); err != nil {
125			return err
126		}
127		if *file == "" || *spec == "" {
128			return fmt.Errorf("create requires --file and --schema")
129		}
130		schema, err := parseSchema(*spec)
131		if err != nil {
132			return err
133		}
134		if _, err := os.Stat(*file); err == nil {
135			return fmt.Errorf("file %s already exists", *file)
136		}
137		if _, err := columna.WriteFile(*file, schema, nil, columna.DefaultMaxPage, nil); err != nil {
138			return err
139		}
140		fmt.Printf("created %s with %d columns\n", *file, len(schema.Columns))
141		return nil
142	}
143	
144	func runWrite(args []string) error {
145		set := flag.NewFlagSet("write", flag.ContinueOnError)
146		file := set.String("file", "", "table file path")
147		spec := set.String("schema", "", "schema used when the file is created")
148		rowsPath := set.String("rows", "", "JSONL or JSON array file")
149		appendMode := set.Bool("append", false, "append a row group to an existing file")
150		maxPage := set.Int("max-page-values", columna.DefaultMaxPage, "values per page")
151		if err := set.Parse(args); err != nil {
152			return err
153		}
154		if *file == "" || *rowsPath == "" {
155			return fmt.Errorf("write requires --file and --rows")
156		}
157		raw, err := os.ReadFile(*rowsPath)
158		if err != nil {
159			return err
160		}
161		var schema columna.Schema
162		if *appendMode {
163			table, err := columna.OpenPath(*file)
164			if err != nil {
165				return err
166			}
167			schema = table.Schema
168		} else {
169			if *spec == "" {
170				return fmt.Errorf("write requires --schema when creating a new file")
171			}
172			schema, err = parseSchema(*spec)
173			if err != nil {
174				return err
175			}
176		}
177		rows, err := columna.DecodeLines(schema, raw)
178		if err != nil {
179			return err
180		}
181		if len(rows) == 0 {
182			return fmt.Errorf("no rows found in %s", *rowsPath)
183		}
184		if *appendMode {
185			parsed, err := columna.AppendRows(*file, schema, rows, *maxPage, nil)
186			if err != nil {
187				return err
188			}
189			stats := parsed.Stats()
190			fmt.Printf("appended %d rows to %s (%d rows, %d row groups)\n", len(rows), *file, stats.RowCount, stats.RowGroupCount)
191			return nil
192		}
193		parsed, err := columna.WriteFile(*file, schema, [][]columna.Row{rows}, *maxPage, nil)
194		if err != nil {
195			return err
196		}
197		fmt.Printf("wrote %d rows to %s (%d row groups)\n", len(rows), *file, parsed.Stats().RowGroupCount)
198		return nil
199	}
200	
201	func runQuery(args []string) error {
202		set := flag.NewFlagSet("query", flag.ContinueOnError)
203		file := set.String("file", "", "table file path")
204		selectSpec := set.String("select", "", "comma separated projection")
205		whereSpec := multiFlag{}
206		set.Var(&whereSpec, "where", "predicate, e.g. 'age >= 30' or 'age between 1 9'")
207		aggSpec := multiFlag{}
208		set.Var(&aggSpec, "agg", "aggregate, e.g. 'sum:amount' or 'count'")
209		limit := set.Int("limit", -1, "maximum rows")
210		noPushdown := set.Bool("no-pushdown", false, "disable page statistics pruning")
211		if err := set.Parse(args); err != nil {
212			return err
213		}
214		if *file == "" {
215			return fmt.Errorf("query requires --file")
216		}
217		table, err := columna.OpenPath(*file)
218		if err != nil {
219			return err
220		}
221		query := columna.Query{Table: table.Name}
222		if *selectSpec != "" {
223			for _, name := range strings.Split(*selectSpec, ",") {
224				if name = strings.TrimSpace(name); name != "" {
225					query.Projection = append(query.Projection, name)
226				}
227			}
228		}
229		for _, predicate := range whereSpec {
230			parsed, err := parsePredicate(predicate)
231			if err != nil {
232				return err
233			}
234			query.Predicates = append(query.Predicates, parsed)
235		}
236		for _, aggregate := range aggSpec {
237			parts := strings.SplitN(strings.TrimSpace(aggregate), ":", 2)
238			entry := columna.Aggregate{Func: parts[0]}
239			if len(parts) == 2 {
240				entry.Column = strings.TrimSpace(parts[1])
241			}
242			query.Aggregates = append(query.Aggregates, entry)
243		}
244		if *limit >= 0 {
245			query.Limit = limit
246		}
247		pushdown := !*noPushdown
248		query.Pushdown = &pushdown
249		result, err := columna.Execute(table, query)
250		if err != nil {
251			return err
252		}
253		out, err := json.Marshal(result)
254		if err != nil {
255			return err
256		}
257		fmt.Println(string(out))
258		return nil
259	}
260	
261	func parsePredicate(text string) (columna.Predicate, error) {
262		fields := strings.Fields(strings.TrimSpace(text))
263		if len(fields) == 0 {
264			return columna.Predicate{}, fmt.Errorf("empty predicate")
265		}
266		predicate := columna.Predicate{Column: fields[0]}
267		switch {
268		case len(fields) == 3 && fields[1] == "between":
269			return predicate, fmt.Errorf("between needs a lower and an upper bound")
270		case len(fields) == 4 && fields[1] == "between":
271			lo, err := parseLiteral(fields[2])
272			if err != nil {
273				return predicate, err
274			}
275			hi, err := parseLiteral(fields[3])
276			if err != nil {
277				return predicate, err
278			}
279			predicate.Op = columna.OpBetween
280			predicate.Lo, predicate.Hi = lo, hi
281			return predicate, nil
282		case len(fields) == 3:
283			value, err := parseLiteral(fields[2])
284			if err != nil {
285				return predicate, err
286			}
287			predicate.Op = fields[1]
288			predicate.Value = value
289			return predicate, nil
290		}
291		return predicate, fmt.Errorf("cannot parse predicate %q", text)
292	}
293	
294	func parseLiteral(text string) (*columna.Value, error) {
295		if text == "true" || text == "false" {
296			value := columna.BoolValue(text == "true")
297			return &value, nil
298		}
299		if number, err := strconv.ParseInt(text, 10, 64); err == nil {
300			value := columna.IntValue(number)
301			return &value, nil
302		}
303		if number, err := strconv.ParseFloat(text, 64); err == nil {
304			value := columna.FloatValue(number)
305			return &value, nil
306		}
307		value := columna.StringValue(strings.Trim(text, `"'`))
308		return &value, nil
309	}
310	
311	func runStats(args []string) error {
312		set := flag.NewFlagSet("stats", flag.ContinueOnError)
313		file := set.String("file", "", "table file path")
314		if err := set.Parse(args); err != nil {
315			return err
316		}
317		if *file == "" {
318			return fmt.Errorf("stats requires --file")
319		}
320		table, err := columna.OpenPath(*file)
321		if err != nil {
322			return err
323		}
324		checksum, err := table.Checksum()
325		if err != nil {
326			return err
327		}
328		out, err := json.Marshal(columna.StatsResult{
329			Table:    table.Name,
330			Schema:   table.Schema,
331			Stats:    table.Stats(),
332			Checksum: checksum,
333		})
334		if err != nil {
335			return err
336		}
337		fmt.Println(string(out))
338		return nil
339	}
340	
341	type multiFlag []string
342	
343	func (m *multiFlag) String() string { return strings.Join(*m, ",") }
344	
345	func (m *multiFlag) Set(value string) error {
346		*m = append(*m, value)
347		return nil
348	}
