	}
	table, err := columna.OpenPath(path)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	return table
}

func rowsJSON(t *testing.T, result columna.QueryResult) string {
	t.Helper()
	raw, err := json.Marshal(result.Rows)
	if err != nil {
		t.Fatal(err)
	}
