package columna

import (
	"math"
	"sort"
)

// Statistics-driven scan cost estimation.
//
// EstimateScanCost ranks candidate files or shards using metadata only: it
// never reads page payloads and never writes or rewrites a file. The estimate
// first drops columns the query does not read, then prunes row groups and pages
// whose recorded statistics make a predicate match impossible, and finally
// combines the surviving bytes, the values that must be decoded and the rows
// that must be processed into one unitless cost. The weights are fixed so that
// the same request and the same metadata always produce the same cost.

// Fixed cost-model weights. The cost of one candidate is
//
//	bytes/1000 + 0.01*decodedValues + 0.001*processedRows.
const (
	costBytesPerPoint    = 1000.0
	costPerDecodedValue  = 0.01
	costPerProcessedRow  = 0.001
	costSelectivityFloor = 1e-12
)

// InvalidArgumentError reports a candidate that violates the estimator input
// contract: an empty candidate list, negative counts, more nulls than rows, a
// maximum below the minimum or more distinct values than non-null rows.
type InvalidArgumentError struct{ Message string }

func (e *InvalidArgumentError) Error() string { return e.Message }

func invalidf(format string, args ...any) error {
	return &InvalidArgumentError{Message: sprintf(format, args...)}
}

// UnsupportedPredicateError reports a predicate the cost model cannot price.
// Unsupported predicates are rejected for every candidate before any estimate
// is returned, so a caller never receives a partially estimated result.
type UnsupportedPredicateError struct{ Message string }

func (e *UnsupportedPredicateError) Error() string { return e.Message }

func unsupportedf(format string, args ...any) error {
	return &UnsupportedPredicateError{Message: sprintf(format, args...)}
}

// CostPredicate is one filter condition to price. Type is the column type the
// literal is compared against: one of TypeInt64, TypeFloat64, TypeBool and
// TypeString. A condition is either:
//
//   - IsNull/IsNotNull: Value, Lo and Hi are ignored;
//   - Op one of "=", "<", ">", "<=", ">=": Value holds the literal;
//   - Op "between": Lo and Hi hold the inclusive bounds.
type CostPredicate struct {
	Column   string
	Type     string
	Op       string
	Value    *Value
	Lo, Hi   *Value
	IsNull    bool
	IsNotNull bool
}

// PageStat is the metadata of one page of one column. Min/Max describe the
// non-null values; Set false means the boundaries are unknown (an all-NULL page,
// or a source that simply does not record them). Nulls must never exceed the
// page's row count and Distinct must never exceed its non-null row count.
type PageStat struct {
	Rows     int64
	Bytes    int64
	Nulls    int64
	Distinct int64
	Set      bool
	Min      Value
	Max      Value
}

// GroupStat is one row group. Pages holds one entry per column, in the same
// order and with the same keys as CandidateSource.Columns; an empty entry means
// the column declares no pages in this row group.
type GroupStat struct {
	Rows  int64
	Pages map[string][]PageStat
}

// ColumnStatInput is the candidate-wide summary of one column.
type ColumnStatInput struct {
	Nulls    int64
	Distinct int64
	Set      bool
	Min      Value
	Max      Value
}

// CandidateSource is one file or shard the estimator may scan.
type CandidateSource struct {
	// Name identifies the candidate in the report. It does not affect cost.
	Name string
	// Rows is the total row count of the candidate.
	Rows int64
	// Groups holds the row groups in scan order; an empty list describes a
	// candidate without row group boundaries.
	Groups []GroupStat
	// Columns maps every column name to its per-page byte counts. Each inner
	// slice is the pages of the column in page index order across the whole
	// candidate; byte counts may instead be repeated per row group as long as
	// their concatenation matches this order.
	Columns map[string][]int64
	// Stats holds the candidate-wide per-column summary.
	Stats map[string]ColumnStatInput
}

// ScanRequest is the public estimation input: the candidate sources, the
// columns the scan must read, the columns the query projects, the predicates,
// an optional limit and the number of rows a sort must consume.
type ScanRequest struct {
	Sources     []CandidateSource
	// ReadColumns lists every column the scan touches (projection plus
	// predicate and sort columns). Columns outside this list cost nothing.
	ReadColumns []string
	// ProjectionColumns lists the returned columns; it must be a subset of
	// ReadColumns. Empty means the read columns are all projected.
	ProjectionColumns []string
	Predicates        []CostPredicate
	// Limit, when non-negative, bounds the rows returned; a nil limit is
	// unlimited. Limit zero short-circuits to a zero-cost plan.
	Limit *int64
	// SortRows is the number of leading rows a sort must consume before it can
	// return anything (0 when the query does not sort). It delays the limit
	// early stop.
	SortRows int64
}

// CandidateCost is the estimate of one candidate, in input order.
type CandidateCost struct {
	Source              string  `json:"source"`
	RowGroups           int     `json:"row_groups"`
	Pages               int64   `json:"pages"`
	Bytes               int64   `json:"bytes"`
	DecodedValues       int64   `json:"decoded_values"`
	FilteredRows        int64   `json:"filtered_rows"`
	ReturnedRows        int64   `json:"returned_rows"`
	ProcessedRows       int64   `json:"processed_rows"`
	Cost                float64 `json:"cost"`
	IncompleteStatistics bool   `json:"incomplete_statistics"`
	Reason              string  `json:"reason"`
}

// ScanCostResult is the estimator output: one estimate per candidate in input
// order and the name of the cheapest candidate.
type ScanCostResult struct {
	Candidates []CandidateCost `json:"candidates"`
	// Selected is the cheapest candidate; it is empty when no candidate is
	// chosen (limit zero) or every candidate pruned away entirely.
	Selected string `json:"selected"`
}

// EstimateScanCost prices the candidate sources without reading their data.
//
// The result preserves input order. The cheapest candidate wins, ties broken
// in favour of the first input candidate; when every candidate has zero cost
// (everything pruned, or no rows read) the first candidate is selected. Limit
// zero returns zero-cost estimates and selects nobody.
func EstimateScanCost(request ScanRequest) (ScanCostResult, error) {
	if len(request.Sources) == 0 {
		return ScanCostResult{}, invalidf("at least one candidate source is required")
	}
	if request.SortRows < 0 {
		return ScanCostResult{}, invalidf("sort_rows must not be negative")
	}
	if request.Limit != nil && *request.Limit < 0 {
		return ScanCostResult{}, invalidf("limit must not be negative")
	}
	if err := validatePredicates(request.Predicates); err != nil {
		return ScanCostResult{}, err
	}
	read, projection, err := request.columnSets()
	if err != nil {
		return ScanCostResult{}, err
	}
	for i := range request.Sources {
		if err := validateCandidate(request.Sources[i], read); err != nil {
			return ScanCostResult{}, err
		}
	}

	result := ScanCostResult{Candidates: make([]CandidateCost, len(request.Sources))}
	limit := int64(-1)
	if request.Limit != nil {
		limit = *request.Limit
	}
	for i := range request.Sources {
		result.Candidates[i] = estimateCandidate(request.Sources[i], read, projection, request.Predicates, limit, request.SortRows)
	}
	if limit == 0 {
		return result, nil
	}
	selected := -1
	for i := range result.Candidates {
		if selected < 0 || result.Candidates[i].Cost < result.Candidates[selected].Cost {
			selected = i
		}
	}
	if selected >= 0 {
		result.Selected = request.Sources[selected].Name
	}
	return result, nil
}

func (r ScanRequest) columnSets() (map[string]bool, map[string]bool, error) {
	read := map[string]bool{}
	for _, name := range r.ReadColumns {
		if name == "" {
			return nil, nil, invalidf("read column names must not be empty")
		}
		if read[name] {
			return nil, nil, invalidf("read column %q is listed more than once", name)
		}
		read[name] = true
	}
	projection := map[string]bool{}
	for _, name := range r.ProjectionColumns {
		if !read[name] {
			return nil, nil, invalidf("projection column %q is not among the read columns", name)
		}
		if projection[name] {
			return nil, nil, invalidf("projection column %q is listed more than once", name)
		}
		projection[name] = true
	}
	if len(projection) == 0 {
		for name := range read {
			projection[name] = true
		}
	}
	return read, projection, nil
}

// validatePredicates rejects operators the model cannot price before any
// candidate is inspected, so failure never depends on candidate order.
func validatePredicates(predicates []CostPredicate) error {
	for i, p := range predicates {
		if p.Column == "" {
			return invalidf("predicate %d is missing a column", i)
		}
		if p.IsNull || p.IsNotNull {
			if p.Op != "" || p.Value != nil || p.Lo != nil || p.Hi != nil {
				return invalidf("predicate %d on %q mixes IS NULL with another operator", i, p.Column)
			}
			continue
		}
		switch p.Op {
		case OpEq, OpLt, OpGt, OpLte, OpGte:
			if p.Value == nil {
				return invalidf("predicate %d on %q requires a value", i, p.Column)
			}
			if p.Value.Null || p.Value.Kind != p.Type {
				return invalidf("predicate %d on %q has a value that does not match its column type %q", i, p.Column, p.Type)
			}
			if p.Type == TypeString && p.Op != OpEq {
				return unsupportedf("string column %q does not support ordering operator %q", p.Column, p.Op)
			}
			if p.Type != TypeInt64 && p.Type != TypeFloat64 && p.Type != TypeBool && p.Type != TypeString {
				return unsupportedf("predicate %d on %q has unsupported column type %q", i, p.Column, p.Type)
			}
		case OpBetween:
			if p.Lo == nil || p.Hi == nil {
				return invalidf("between predicate on %q requires lo and hi", p.Column)
			}
			if p.Lo.Null || p.Hi.Null || p.Lo.Kind != p.Type || p.Hi.Kind != p.Type {
				return invalidf("between predicate on %q has bounds that do not match its column type %q", p.Column, p.Type)
			}
			if compareValues(*p.Lo, *p.Hi) > 0 {
				return invalidf("between predicate on %q has lo above hi", p.Column)
			}
			if p.Type != TypeInt64 && p.Type != TypeFloat64 && p.Type != TypeString {
				return unsupportedf("between predicate on %q has unsupported column type %q", p.Column, p.Type)
			}
		default:
			return unsupportedf("predicate %d on %q uses unsupported operator %q", i, p.Column, p.Op)
		}
	}
	return nil
}

func validateCandidate(source CandidateSource, read map[string]bool) error {
	if source.Rows < 0 {
		return invalidf("candidate %q has a negative row count", source.Name)
	}
	if source.Columns == nil {
		return invalidf("candidate %q is missing per-column byte counts", source.Name)
	}
	if source.Stats == nil {
		return invalidf("candidate %q is missing per-column statistics", source.Name)
	}
	// Per-column invariants hold independently of row groups.
	for column := range read {
		bytes, ok := source.Columns[column]
		if !ok {
			return invalidf("candidate %q is missing byte counts for read column %q", source.Name, column)
		}
		stats, ok := source.Stats[column]
		if !ok {
			return invalidf("candidate %q is missing statistics for read column %q", source.Name, column)
		}
		for i, n := range bytes {
			if n < 0 {
				return invalidf("candidate %q column %q page %d has negative byte count", source.Name, column, i)
			}
		}
		if stats.Nulls < 0 {
			return invalidf("candidate %q column %q has a negative null count", source.Name, column)
		}
		if stats.Distinct < 0 {
			return invalidf("candidate %q column %q has a negative distinct count", source.Name, column)
		}
		if stats.Nulls > source.Rows {
			return invalidf("candidate %q column %q reports %d nulls but only %d rows", source.Name, column, stats.Nulls, source.Rows)
		}
		if stats.Distinct > source.Rows-stats.Nulls {
			return invalidf("candidate %q column %q reports %d distinct values but only %d non-null rows", source.Name, column, stats.Distinct, source.Rows-stats.Nulls)
		}
		if stats.Set {
			if stats.Min.Null || stats.Max.Null {
				return invalidf("candidate %q column %q has incomplete min/max flagged as present", source.Name, column)
			}
			if stats.Min.Kind != column || stats.Max.Kind != column {
				return invalidf("candidate %q column %q min/max do not match the column type %q", source.Name, column, column)
			}
			if compareValues(stats.Min, stats.Max) > 0 {
				return invalidf("candidate %q column %q has min above max", source.Name, column)
			}
		}
	}

	groupRows := int64(0)
	for g := range source.Groups {
		group := source.Groups[g]
		if group.Rows < 0 {
			return invalidf("candidate %q row group %d has a negative row count", source.Name, g)
		}
		groupRows += group.Rows
		if group.Pages == nil {
			if group.Rows != 0 {
				return invalidf("candidate %q row group %d is missing page statistics", source.Name, g)
			}
			continue
		}
		for column := range read {
			pages := group.Pages[column]
			pageRows := int64(0)
			for p, page := range pages {
				if page.Rows < 0 {
					return invalidf("candidate %q row group %d column %q page %d has a negative row count", source.Name, g, column, p)
				}
				if page.Bytes < 0 {
					return invalidf("candidate %q row group %d column %q page %d has negative byte count", source.Name, g, column, p)
				}
				if page.Nulls < 0 {
					return invalidf("candidate %q row group %d column %q page %d has a negative null count", source.Name, g, column, p)
				}
				if page.Distinct < 0 {
					return invalidf("candidate %q row group %d column %q page %d has a negative distinct count", source.Name, g, column, p)
				}
				if page.Nulls > page.Rows {
					return invalidf("candidate %q row group %d column %q page %d reports %d nulls but holds %d rows", source.Name, g, column, p, page.Nulls, page.Rows)
				}
				if page.Distinct > page.Rows-page.Nulls {
					return invalidf("candidate %q row group %d column %q page %d reports %d distinct values but only %d non-null rows", source.Name, g, column, p, page.Distinct, page.Rows-page.Nulls)
				}
				if page.Set {
					if page.Min.Null || page.Max.Null {
						return invalidf("candidate %q row group %d column %q page %d has incomplete min/max flagged as present", source.Name, g, column, p)
					}
					if page.Min.Kind != column || page.Max.Kind != column {
						return invalidf("candidate %q row group %d column %q page %d min/max do not match the column type %q", source.Name, g, column, p, column)
					}
					if compareValues(page.Min, page.Max) > 0 {
						return invalidf("candidate %q row group %d column %q page %d has min above max", source.Name, g, column, p)
					}
				}
				pageRows += page.Rows
			}
			if pageRows > group.Rows {
				return invalidf("candidate %q row group %d column %q pages cover %d rows but the group holds %d", source.Name, g, column, pageRows, group.Rows)
			}
		}
	}
	if len(source.Groups) > 0 && groupRows != source.Rows {
		return invalidf("candidate %q row groups cover %d rows but the candidate declares %d", source.Name, groupRows, source.Rows)
	}
	return nil
}

// estimateCandidate prices one source. The steps mirror the description in
// EstimateScanCost: project, prune groups and pages, then size and select.
func estimateCandidate(source CandidateSource, read, projection map[string]bool, predicates []CostPredicate, limit int64, sortRows int64) CandidateCost {
	estimate := CandidateCost{Source: source.Name}
	if limit == 0 {
		estimate.Reason = "limit is zero: no rows are read"
		return estimate
	}

	readCols := sortedKeys(read)
	byColumn := map[string][]CostPredicate{}
	for _, p := range predicates {
		byColumn[p.Column] = append(byColumn[p.Column], p)
	}

	groups := source.Groups
	freeBoundary := len(groups) == 0
	if freeBoundary {
		// A source without row group boundaries is one implicit group, so group
		// pruning stays binary and every byte still belongs to a page.
		groups = []GroupStat{{Rows: source.Rows, Pages: map[string][]PageStat{}}}
	}

	type survivingPage struct {
		rows     int64
		bytes    int64
		nulls    int64
		distinct int64
		set      bool
		min, max Value
	}
	surviving := make(map[string][]survivingPage, len(readCols))
	consumed := make(map[string]int64, len(readCols)) // page byte counts already attributed
	survivingRows := int64(0)

	for g := range groups {
		group := groups[g]
		if group.Rows == 0 {
			continue
		}
		// Group pruning: the group is dropped only when a column used by a
		// predicate provably cannot match inside it. Missing statistics never
		// prune.
		if !groupCanMatch(group, source, byColumn, freeBoundary) {
			estimate.Reason = appendReason(estimate.Reason, "row group "+itoa(g)+" pruned by statistics")
			continue
		}
		estimate.RowGroups++
		survivingRows += group.Rows
		for _, column := range readCols {
			pages := group.Pages[column]
			if freeBoundary {
				pages = implicitPages(source, column)
			}
			columnPredicates := byColumn[column]
			for p, page := range pages {
				if page.Rows == 0 {
					consumed[column] += page.Bytes
					continue
				}
				if !pageCanMatchCost(page, columnPredicates) {
					consumed[column] += page.Bytes
					continue
				}
				surviving[column] = append(surviving[column], survivingPage{
					rows: page.Rows, bytes: page.Bytes, nulls: page.Nulls,
					distinct: page.Distinct, set: page.Set, min: page.Min, max: page.Max,
				})
				_ = p
			}
		}
	}

	var bytes int64
	var decoded int64
	incomplete := false
	for _, column := range readCols {
		pages := surviving[column]
		estimate.Pages += int64(len(pages))
		columnBytes := int64(0)
		columnValues := int64(0)
		for _, page := range pages {
			columnBytes += page.bytes
			columnValues += page.rows
		}
		// Columns absent from the per-page byte map of a group-free source use
		// the candidate-wide byte list directly.
		if len(source.Groups) == 0 {
			columnBytes = sumBytes(source.Columns[column], consumed[column])
		}
		bytes += columnBytes
		decoded += columnValues
		if columnStatisticsIncomplete(source.Stats[column]) || pagesIncomplete(pages) {
			incomplete = true
		}
	}
	estimate.Bytes = bytes
	estimate.DecodedValues = decoded
	estimate.ProcessedRows = survivingRows

	// The surviving rows are the rows the engine must process; the predicate
	// selectivities then estimate how many pass the filter.
	filtered := survivingRowsAsFloat(survivingRows, predicates, source, surviving, readCols)
	estimate.FilteredRows = clampRound(filtered)
	estimate.IncompleteStatistics = incomplete

	returned := estimate.FilteredRows
	if limit >= 0 && returned > limit {
		returned = limit
	}
	estimate.ReturnedRows = returned

	estimate.Cost = float64(bytes)/costBytesPerPoint +
		costPerDecodedValue*float64(decoded) +
		costPerProcessedRow*float64(survivingRows)

	if estimate.RowGroups == 0 && survivingRows == 0 {
		estimate.Reason = prependReason(estimate.Reason, "statistics pruned every row group")
	} else {
		estimate.Reason = prependReason(estimate.Reason, buildReason(estimate, incomplete, limit, sortRows))
	}
	return estimate
}

// groupCanMatch applies candidate-wide statistics to a row group when the group
// carries no page table of its own, and the page boundaries otherwise. A
// predicate column with no statistic in the group is treated as matchable.
func groupCanMatch(group GroupStat, source CandidateSource, byColumn map[string][]CostPredicate, freeBoundary bool) bool {
	for column, predicates := range byColumn {
		pages := group.Pages[column]
		if freeBoundary {
			pages = implicitPages(source, column)
		}
		if len(pages) == 0 {
			// No page metadata for this column in the group: fall back to the
			// candidate-wide summary, and keep the group when it is missing.
			stats, ok := source.Stats[column]
			if !ok || !stats.Set {
				continue
			}
			for _, p := range predicates {
				if !summaryCanMatch(stats, stats.Nulls, group.Rows, p) {
					return false
				}
			}
			continue
		}
		anyPage := false
		for _, page := range pages {
			if pageCanMatchCost(page, predicates) {
				anyPage = true
				break
			}
		}
		if !anyPage {
			return false
		}
	}
	return true
}

// pageCanMatchCost is the estimator analogue of Predicate.pageMatches: it
// returns false only when no row in the page can satisfy every predicate on the
// column. Missing boundaries never prune.
func pageCanMatchCost(page PageStat, predicates []CostPredicate) bool {
	if page.Rows == 0 {
		return false
	}
	for _, p := range predicates {
		if !onePredicatePossible(page, p) {
			return false
		}
	}
	return true
}

func onePredicatePossible(page PageStat, p CostPredicate) bool {
	if p.IsNull {
		return page.Nulls > 0
	}
	if p.IsNotNull {
		return page.Nulls < page.Rows
	}
	if page.Nulls == page.Rows {
		return false // NULL never satisfies a comparison
	}
	if !page.Set {
		return true
	}
	switch p.Op {
	case OpBetween:
		return compareValues(page.Max, *p.Lo) >= 0 && compareValues(page.Min, *p.Hi) <= 0
	case OpEq:
		return compareValues(page.Min, *p.Value) <= 0 && compareValues(page.Max, *p.Value) >= 0
	case OpLt:
		return compareValues(page.Min, *p.Value) < 0
	case OpLte:
		return compareValues(page.Min, *p.Value) <= 0
	case OpGt:
		return compareValues(page.Max, *p.Value) > 0
	case OpGte:
		return compareValues(page.Max, *p.Value) >= 0
	}
	return true
}

func summaryCanMatch(stats ColumnStatInput, nulls, rows int64, p CostPredicate) bool {
	return onePredicatePossible(PageStat{Rows: rows, Nulls: nulls, Set: stats.Set, Min: stats.Min, Max: stats.Max}, p)
}

// implicitPages builds page statistics for a source without row groups from
// the candidate-wide byte list and null counts spread evenly. The page count is
// the byte list length; statistics come from the candidate summary and stay
// conservative (a single shared min/max and distinct count).
func implicitPages(source CandidateSource, column string) []PageStat {
	byteCounts := source.Columns[column]
	if len(byteCounts) == 0 {
		return nil
	}
	stats := source.Stats[column]
	pages := make([]PageStat, len(byteCounts))
	rows := source.Rows
	nonNull := rows - stats.Nulls
	for i := range byteCounts {
		pages[i].Bytes = byteCounts[i]
	}
	if rows == 0 {
		return pages
	}
	// Spread rows, nulls and distinct values across pages without exceeding the
	// recorded totals; the last page absorbs the remainder. Allocated counts
	// only feed validation-free estimation, never pruning boundaries, so an
	// even split is a deliberately conservative shape.
	assignedRows := int64(0)
	assignedNulls := int64(0)
	assignedDistinct := int64(0)
	for i := range pages {
		remaining := int64(len(pages) - i)
		pr := (rows - assignedRows) / remaining
		pn := (stats.Nulls - assignedNulls) / remaining
		pd := (stats.Distinct - assignedDistinct) / remaining
		if i == len(pages)-1 {
			pr = rows - assignedRows
			pn = stats.Nulls - assignedNulls
			pd = stats.Distinct - assignedDistinct
		}
		if pn > pr {
			pn = pr
		}
		if pd > pr-pn {
			pd = pr - pn
		}
		pages[i].Rows = pr
		pages[i].Nulls = pn
		pages[i].Distinct = pd
		if stats.Set {
			pages[i].Set = true
			pages[i].Min = stats.Min
			pages[i].Max = stats.Max
		}
		assignedRows += pr
		assignedNulls += pn
		assignedDistinct += pd
	}
	_ = nonNull
	return pages
}

func sumBytes(all []int64, consumed int64) int64 {
	var total int64
	for _, n := range all {
		total += n
	}
	return total - consumed
}

func columnStatisticsIncomplete(stats ColumnStatInput) bool {
	return !stats.Set || stats.Distinct <= 0
}

func pagesIncomplete(pages []struct {
	rows     int64
	bytes    int64
	nulls    int64
	distinct int64
	set      bool
	min, max Value
}) bool {
	for _, page := range pages {
		if !page.set || page.distinct <= 0 {
			return true
		}
	}
	return false
}

// survivingRowsAsFloat multiplies the per-predicate selectivities over the
// surviving rows. Selectivity is computed per column from its surviving pages
// and combined by independence, matching the documented formulas. Missing
// statistics contribute selectivity one and flag the estimate incomplete.
func survivingRowsAsFloat(rows int64, predicates []CostPredicate, source CandidateSource, surviving map[string][]survivingPageInfo, _ []string) float64 {
	if rows <= 0 || len(predicates) == 0 {
		return float64(rows)
	}
	combined := 1.0
	seen := map[string]bool{}
	for _, p := range predicates {
		if seen[p.Column] {
			continue
		}
		seen[p.Column] = true
		combined *= columnSelectivity(p.Column, filterColumn(predicates, p.Column), surviving[p.Column])
	}
	return float64(rows) * combined
}

type survivingPageInfo = struct {
	rows     int64
	bytes    int64
	nulls    int64
	distinct int64
	set      bool
	min, max Value
}

func filterColumn(predicates []CostPredicate, column string) []CostPredicate {
	out := make([]CostPredicate, 0, 1)
	for _, p := range predicates {
		if p.Column == column {
			out = append(out, p)
		}
	}
	return out
}

// columnSelectivity weights the per-predicate page selectivities by page rows.
// Pages with no usable statistic contribute one, which keeps the estimate
// conservative and is reported as incomplete statistics by the caller.
func columnSelectivity(column string, predicates []CostPredicate, pages []survivingPageInfo) float64 {
	var totalRows int64
	var weighted float64
	for _, page := range pages {
		totalRows += page.rows
		s := 1.0
		for _, p := range predicates {
			s *= predicateSelectivity(page, p)
			if s < costSelectivityFloor {
				s = costSelectivityFloor
			}
		}
		weighted += float64(page.rows) * s
	}
	if totalRows == 0 {
		return 1.0
	}
	return weighted / float64(totalRows)
}

// predicateSelectivity implements the documented estimates:
//
//   - "=": non-null fraction divided by the number of distinct values;
//   - range comparisons and between: overlap of the predicate's comparable
//     interval with [min, max], times the non-null fraction;
//   - IS NULL / IS NOT NULL: the null / non-null fraction.
//
// Any missing statistic yields one rather than a zero cost.
func predicateSelectivity(page survivingPageInfo, p CostPredicate) float64 {
	nonNullFraction := 1.0
	if page.rows > 0 {
		nonNullFraction = float64(page.rows-page.nulls) / float64(page.rows)
	}
	if p.IsNull {
		if page.rows == 0 {
			return 1
		}
		return float64(page.nulls) / float64(page.rows)
	}
	if p.IsNotNull {
		return nonNullFraction
	}
	if !page.set {
		return 1
	}
	switch p.Op {
	case OpEq:
		// An equality outside the recorded range cannot match; inside it the
		// uniform-distribution estimate is non-null fraction / distinct count.
		if compareValues(page.min, *p.Value) > 0 || compareValues(page.max, *p.Value) < 0 {
			return 0
		}
		if page.distinct <= 0 {
			return 1
		}
		return nonNullFraction / float64(page.distinct)
	case OpBetween:
		return rangeSelectivity(page, p.Lo, p.Hi, nonNullFraction)
	case OpLt, OpLte, OpGt, OpGte:
		lo, hi := comparisonBounds(p)
		return rangeSelectivity(page, lo, hi, nonNullFraction)
	}
	return 1
}

func comparisonBounds(p CostPredicate) (*Value, *Value) {
	// Turn a one-sided comparison into a half-open interval over the value
	// domain so one overlap routine prices every range predicate.
	switch p.Op {
	case OpLt, OpLte:
		return domainMin(p.Type), p.Value
	case OpGt, OpGte:
		return p.Value, domainMax(p.Type)
	}
	return p.Value, p.Value
}

func rangeSelectivity(page survivingPageInfo, lo, hi *Value, nonNullFraction float64) float64 {
	if lo == nil || hi == nil {
		return 1
	}
	if compareValues(page.max, *lo) < 0 || compareValues(page.min, *hi) > 0 {
		return 0
	}
	span, ok := valueSpan(page.min, page.max)
	if !ok || span <= 0 {
		// String and bool ranges cannot be measured numerically; fall back to
		// the non-null fraction when the intervals overlap.
		return nonNullFraction
	}
	low, high, ok := numericBounds(lo, hi, page.min.Kind)
	if !ok {
		return 1
	}
	overlapMin := math.Max(low, minNumeric(page.min))
	overlapMax := math.Min(high, maxNumeric(page.max))
	if overlapMax < overlapMin {
		return 0
	}
	return (overlapMax - overlapMin) / span * nonNullFraction
}

func numericBounds(lo, hi *Value, kind string) (float64, float64, bool) {
	if lo.Kind != kind || hi.Kind != kind {
		return 0, 0, false
	}
	return boundNumeric(lo), boundNumeric(hi), true
}

func valueSpan(min, max Value) (float64, bool) {
	a, aOK := min.Number()
	b, bOK := max.Number()
	if !aOK || !bOK {
		return 0, false
	}
	return b - a, true
}

func minNumeric(v Value) float64 {
	n, _ := v.Number()
	return n
}

func maxNumeric(v Value) float64 {
	n, _ := v.Number()
	return n
}

func boundNumeric(v Value) float64 {
	switch v.Kind {
	case TypeInt64:
		return float64(v.Int)
	case TypeFloat64:
		return v.Float
	case TypeBool:
		if v.Bool {
			return 1
		}
		return 0
	}
	return 0
}

func domainMin(typ string) *Value {
	switch typ {
	case TypeInt64:
		v := IntValue(math.MinInt64)
		return &v
	case TypeFloat64:
		v := FloatValue(math.Inf(-1))
		return &v
	case TypeBool:
		v := BoolValue(false)
		return &v
	}
	return nil
}

func domainMax(typ string) *Value {
	switch typ {
	case TypeInt64:
		v := IntValue(math.MaxInt64)
		return &v
	case TypeFloat64:
		v := FloatValue(math.Inf(1))
		return &v
	case TypeBool:
		v := BoolValue(true)
		return &v
	}
	return nil
}

func clampRound(v float64) int64 {
	if math.IsNaN(v) || v < 0 {
		return 0
	}
	if v >= float64(math.MaxInt64) {
		return math.MaxInt64
	}
	return int64(math.Round(v))
}

func buildReason(estimate CandidateCost, incomplete bool, limit, sortRows int64) string {
	parts := []string{}
	if estimate.RowGroups > 0 {
		parts = append(parts, itoa(estimate.RowGroups)+" row groups survive pruning")
	}
	parts = append(parts, itoa64(estimate.Pages)+" pages and "+itoa64(estimate.Bytes)+" bytes read")
	if incomplete {
		parts = append(parts, "statistics incomplete, selectivity assumed one where missing")
	}
	if limit >= 0 {
		parts = append(parts, "limit "+itoa64(limit)+" caps the returned rows")
	}
	if sortRows > 0 {
		parts = append(parts, "sort consumes "+itoa64(sortRows)+" rows before the limit can stop the scan")
	}
	return joinReason(parts)
}

func appendReason(existing, addition string) string {
	if existing == "" {
		return addition
	}
	return existing + "; " + addition
}

func prependReason(existing, addition string) string {
	if addition == "" {
		return existing
	}
	if existing == "" {
		return addition
	}
	return addition + "; " + existing
}

func joinReason(parts []string) string {
	out := ""
	for i, part := range parts {
		if i > 0 {
			out += "; "
		}
		out += part
	}
	return out
}

func sortedKeys(set map[string]bool) []string {
	out := make([]string, 0, len(set))
	for key := range set {
		out = append(out, key)
	}
	sort.Strings(out)
	return out
}

