// validateKinds ensures every recorded boundary of one column shares a type.
// The expected type is taken from Types when the candidate declares it, else
// from a predicate on the column, else from the candidate summary; a column
// with no type hint and no boundaries is left unconstrained.
func validateKinds(label string, source CandidateSource, read map[string]bool, hint map[string]string) error {
	for column := range read {
		expected := hint[column]
		if !validCostType(expected) {
			expected = ""
		}
		note := func(kind string) error {
			if expected == "" {
				expected = kind
				return nil
			}
			if kind != expected {
				return invalidf("candidate %q column %q mixes %s and %s statistics", label, column, expected, kind)
			}
			return nil
		}
		input := source.Columns[column]
		if input.Set {
			if err := note(input.Min.Kind); err != nil {
				return err
			}
		}
		for g, group := range source.Groups {
			if group.Pages == nil {
				continue
			}
			for p, page := range group.Pages[column] {
				if page.Set {
					if err := note(page.Min.Kind); err != nil {
						return invalidf("candidate %q row group %d column %q page %d: %v", label, g, column, p, err)
					}
				}
			}
		}
	}
	return nil
}

